insert into public.agent_profile (id, brand, name, role, creci, phone, whatsapp, email, instagram, city, photo, rating, reviews, years, sold)
insert into public.properties (id, title, type_label, category, price, condo, location, city, beds, baths, area, image, badge, description, features, sort_order)
values
  ('cobertura-ibirapuera', 'Cobertura Vista Ibirapuera', 'Cobertura', 'cobertura', 3850000, 3200, 'Moema', 'São Paulo', 4, 5, 320, '/images/prop-1.jpg', 'Exclusivo', 'Cobertura dúplex com vista definitiva para o Parque Ibirapuera. Terraço gourmet amplo com deck, living em pé-direito duplo, automação completa e acabamentos assinados. Um dos endereços mais desejados de São Paulo.', array['Terraço gourmet com vista 270°', '4 suítes com closets', 'Pé-direito duplo no living', 'Automação e iluminação cênica', '4 vagas de garagem + depósito', 'Lazer completo no condomínio']::text[], 0),
  ('villa-alphaville', 'Villa Contemporânea Alphaville', 'Casa', 'casa', 2890000, 1800, 'Alphaville', 'Barueri', 5, 6, 480, '/images/prop-2.jpg', 'Destaque', 'Casa de arquitetura contemporânea em terreno plano no coração de Alphaville. Linhas retas, esquadrias do piso ao teto, piscina com borda infinita e integração total entre área social e jardim.', array['Piscina com borda infinita', '5 suítes, sendo 1 master no térreo', 'Cozinha gourmet integrada', 'Escritório e academia privativos', 'Energia solar + aquecimento', 'Condomínio com segurança 24h']::text[], 1),
  ('apartamento-jardins', 'Apartamento Jardins Signature', 'Apartamento', 'apartamento', 1780000, 2400, 'Jardins', 'São Paulo', 3, 2, 186, '/images/prop-3.jpg', null, 'Apartamento reformado por escritório renomado nos Jardins. Projeto sofisticado com marcenaria sob medida, piso em carvalho europeu e iluminação natural abundante durante todo o dia.', array['Totalmente reformado', 'Marcenaria sob medida', 'Living para 3 ambientes', 'Varanda com fechamento em vidro', '3 suítes com boa ventilação', '2 vagas demarcadas']::text[], 2),
  ('loft-vila-madalena', 'Loft Brick 1904', 'Loft', 'loft', 940000, 980, 'Vila Madalena', 'São Paulo', 2, 2, 124, '/images/prop-4.jpg', 'Novo', 'Loft industrial autêntico em edifício tombado de 1904, na Vila Madalena. Tijolos aparentes, pé-direito de 4,2 m, mezanino em estrutura metálica e iluminação de galeria. Um apartamento com alma de ateliê.', array['Tijolos aparentes originais', 'Pé-direito de 4,2 metros', 'Mezanino com escritório', 'Edifício histórico tombado', 'A 5 min do metrô Vila Madalena', 'Aceita pet']::text[], 3),
  ('casa-haras-itu', 'Casa de Campo Haras Santa Maria', 'Casa de Campo', 'casa', 2150000, 1500, 'Haras Santa Maria', 'Itu', 4, 4, 520, '/images/prop-5.jpg', null, 'Refúgio de campo a 1h de São Paulo. Arquitetura que abraça a paisagem, varandas amplas voltadas para o pôr do sol, piscina aquecida e pomar. Perfeita para fins de semana em família ou home office definitivo.', array['Terreno de 2.400 m²', 'Piscina aquecida com raia', 'Varanda com vista para o vale', 'Pomar e horta orgânica', 'Espaço gourmet com forno a lenha', 'Portaria 24h e heliponto no condomínio']::text[], 4),
  ('studio-pinheiros', 'Studio Arte Pinheiros', 'Studio', 'studio', 690000, 720, 'Pinheiros', 'São Paulo', 1, 1, 54, '/images/prop-6.jpg', 'Novo', 'Studio projetado para quem vive a cidade. Planta inteligente com integração total, armários ocultos, varanda de frente para o oeste e prédio com rooftop colaborativo. Excelente liquidez para investidores.', array['Projeto de interiores incluso', 'Varanda com vista oeste', 'Rooftop com coworking no prédio', 'Lavanderia coletiva premium', 'A 400 m da Faria Lima', 'Ótimo potencial de locação']::text[], 5);
